<section class="card"><h2><?= e(t('Plan a target GPA')) ?></h2><p class="muted"><?= e(t('Calculate the average grade points needed across your ungraded modules. This uses your saved credit weights and the grade-point scale in Settings.')) ?></p>
<form class="inline" action="/uni" method="get"><input type="hidden" name="view" value="modules"><label><?= e(t('Target GPA')) ?><input type="number" name="target" min="0" max="10" step="0.01" value="<?= e($targetInput) ?>" required></label><button class="secondary"><?= e(t('Calculate')) ?></button></form>
<?php if ($targetPlan): ?><div role="status"><p><strong><?= e(t('Target')) ?> <?= e(number_format($targetPlan['target'],2)) ?></strong> · <?= e($targetPlan['graded_credits'] ?? 0) ?> <?= e(t('graded credits ·')) ?> <?= e($targetPlan['remaining_credits'] ?? 0) ?> <?= e(t('ungraded credits')) ?></p>
<?php if ($targetPlan['status']==='no_scale'): ?><p><?= e(t('Set your grade-point scale in Settings first.')) ?></p>
<?php elseif ($targetPlan['status']==='no_credits'): ?><p><?= e(t('Add modules with credits before calculating a target.')) ?></p>
<?php elseif ($targetPlan['status']==='met'): ?><p><?= e(t('Your recorded grades meet this target. There are no ungraded credits in the plan.')) ?></p>
<?php elseif ($targetPlan['status']==='secured'): ?><p><?= e(t('This target is secured even if the remaining modules receive zero grade points.')) ?></p>
<?php elseif ($targetPlan['status']==='unreachable'): ?><p><?= e(t('This target cannot be reached with the currently recorded grades and remaining credits.')) ?><?php if (isset($targetPlan['required_average'])): ?> <?= e(t('It would need an average of')) ?> <?= e(number_format($targetPlan['required_average'],2)) ?> <?= e(t('points; the highest configured grade is')) ?> <?= e(number_format($targetPlan['max_points'],2)) ?>.<?php endif; ?></p>
<?php else: ?><p><?= e(t('Average needed on ungraded credits:')) ?> <strong><?= e(number_format($targetPlan['required_average'],2)) ?> <?= e(t('grade points')) ?></strong><?= e(t('. If each remaining module receives at least')) ?> <?= e($targetPlan['minimum_grade']) ?> <?= e(t('under your current scale, this target is reachable.')) ?></p><?php endif; ?>
<p class="footnote"><?= e(t('This is a credit-weighted scenario, not a predicted result. Marks needed cannot be calculated until you provide your institution\'s marks-to-grade thresholds.')) ?></p></div><?php endif; ?></section>
